--
-- Drivers, vehicles and driver devices (DEL-4 plan 2.1; data §2.2, §10; domain model §3.5;
-- identity and tenancy §3.2; ADR-0025, ADR-0031, ADR-0034). Three tenant tables with the template
-- policies of 0003, enabled by core_enable_tenant_rls() when the job runs with ELX_RLS=on. elx_app
-- keeps the default SELECT, INSERT, UPDATE, DELETE of 0001 (the staff doors and the driver doors
-- run in the tenant unit of work); elx_platform may only read them (plan 2.1). del_drivers.user_id
-- references the platform-pool core_users row as core_memberships.user_id does; membership_id the
-- core_memberships row that holds the `driver` role. cash_pin_hash is a PHC Argon2id string
-- (ADR-0034); the two-device cap is counted under the driver row lock, so the partial index on
-- active devices is not unique (data §2.2). del_drivers.name is the name this account gave the
-- driver (adversary H-3): no account reads or writes another's name for a shared person. Personal
-- data (data §10): the name, the PIN hash, the app's device id and the push token, tagged
-- pii:driver.
CREATE TABLE "del_driver_devices" (
	"id" uuid PRIMARY KEY NOT NULL,
	"account_id" uuid NOT NULL,
	"driver_id" uuid NOT NULL,
	"device_id" text NOT NULL,
	"platform" text NOT NULL,
	"app_version" text NOT NULL,
	"push_token" text,
	"revoked_at" timestamp with time zone,
	"last_seen_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "del_driver_devices_platform_check" CHECK ("del_driver_devices"."platform" IN ('ios', 'android')),
	CONSTRAINT "del_driver_devices_device_id_check" CHECK (length("del_driver_devices"."device_id") BETWEEN 1 AND 200),
	CONSTRAINT "del_driver_devices_app_version_check" CHECK (length("del_driver_devices"."app_version") BETWEEN 1 AND 64),
	CONSTRAINT "del_driver_devices_push_token_check" CHECK (length("del_driver_devices"."push_token") <= 4096),
	CONSTRAINT "del_driver_devices_version_check" CHECK ("del_driver_devices"."version" >= 1)
);
